-- 경공매 달력 — 정비구역(모아·신통) 안에 뜬 경매·공매 물건을 «매각기일»에 꽂아 본다.
--
-- 종이 달력에 「2025-51160 신통 OO마을 2.44/1.95」식으로 적던 걸 그대로 옮긴 것.
-- 칸을 누르면 행크옥션으로 가고, 관심·임장·입찰예정 태그를 달아 추린다.
-- 행크옥션 엑셀(정비구역 내 경공매물건.xlsx)에서 받아 온 162건을 처음 칸으로 넣는다.
-- 금액은 엑셀의 «만원»을 «원»으로 바꿔 넣는다(앱 전체가 원 단위).

create table if not exists public.sale_items (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,

  zone        text not null,                -- 구역 (신림5 · 산새마을 …)
  case_no     text not null,                -- 2025타경102886 (경매) · 2026-10740-004 (공매)
  source      text not null default '경매',  -- 경매 | 공매
  kind        text,                         -- 다세대 · 오피스텔 · 근린시설 …
  appraisal   numeric(16,0) not null default 0,  -- 감정가 (원)
  min_price   numeric(16,0) not null default 0,  -- 최저가 (원)
  fails       int not null default 0,       -- 유찰 횟수
  sale_date   date not null,                -- 매각기일 · 입찰마감
  address     text,
  tag         text,                         -- 관심 | 임장 | 입찰예정 | 패스 | null
  memo        text,
  url         text,                         -- 행크옥션 물건 링크 (없으면 사건번호로 검색)

  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (user_id, case_no, address)
);

create index if not exists sale_items_user_date_idx on public.sale_items (user_id, sale_date);

create trigger set_updated_at before update on public.sale_items
  for each row execute function public.set_updated_at();

alter table public.sale_items enable row level security;
create policy "own - select" on public.sale_items for select using (auth.uid() = user_id);
create policy "own - insert" on public.sale_items for insert with check (auth.uid() = user_id);
create policy "own - update" on public.sale_items for update using (auth.uid() = user_id);
create policy "own - delete" on public.sale_items for delete using (auth.uid() = user_id);

